#!/usr/bin/env bash
set -euo pipefail

# Fail2Drive Generalization-only qualitative rerun.
# Based on launch_latest_4hz_stage3_ds87_epoch9_fail2drive_seed0_single_lidar_creeping_8gpu.sh.
# This keeps the original checkpoint/controller/creeping/seed settings and only
# enables structured visualization recording for the selected 44 routes.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Accept the historical LONGEST6 variable name used in the original command,
# while forwarding it to the actual Fail2Drive GPU variable.
export LEAD_STAGE3_DS87_EPOCH9_F2D_GPU_IDS="${LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_GPU_IDS:-${LEAD_STAGE3_DS87_EPOCH9_LONGEST6_GPU_IDS:-0,1,2,3,4,5,6,7}}"
export LEAD_STAGE3_DS87_EPOCH9_F2D_CREEP_POINT_SOURCE=single_lidar
export LEAD_STAGE3_DS87_EPOCH9_F2D_RUN_ID="${LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_RUN_ID:-latest_4hz_stage3_ds87_epoch9_fail2drive_seed0_single_lidar_creeping_generalization44_visualization_v1}"
export LEAD_STAGE3_DS87_EPOCH9_F2D_RECORD_COMFORT=1
export LEAD_STAGE3_DS87_EPOCH9_F2D_RECORD_VISUALIZATION=1
export LEAD_STAGE3_DS87_EPOCH9_F2D_REQUIRE_COMFORT_METRICS=1
export LEAD_STAGE3_DS87_EPOCH9_F2D_REQUIRE_VISUALIZATION=1
export LEAD_STAGE3_DS87_EPOCH9_F2D_METRIC_FLUSH_INTERVAL="${LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_FLUSH_INTERVAL:-50}"
export LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_DET_SCORE_THRESHOLD="${LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_DET_SCORE_THRESHOLD:-0.3}"
export LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_MAP_SCORE_THRESHOLD="${LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_MAP_SCORE_THRESHOLD:-0.3}"
export LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_ACTOR_RADIUS_M="${LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_ACTOR_RADIUS_M:-65.0}"

# These are the 44 Generalization routes with route-level DS >= 90 from the
# completed single_lidar_creeping_v2 run. The launcher's strict source preflight
# still validates all 200 official route files and resume uses only this subset.
export LEAD_STAGE3_DS87_EPOCH9_F2D_ROUTE_IDS="${LEAD_STAGE3_DS87_EPOCH9_F2D_VIS_ROUTE_IDS:-Generalization_Animals_1075 Generalization_Animals_1078 Generalization_Animals_1081 Generalization_BadParking_1000 Generalization_BadParking_1003 Generalization_BadParking_1004 Generalization_BadParking_1005 Generalization_BadParking_1006 Generalization_BadParking_1007 Generalization_BadParking_1008 Generalization_ConstructionPedestrian_1010 Generalization_ConstructionPedestrian_1012 Generalization_ConstructionPermutations_1018 Generalization_CustomObstacles_1029 Generalization_FullyBlocked_1030 Generalization_FullyBlocked_1032 Generalization_FullyBlocked_1033 Generalization_FullyBlocked_1034 Generalization_HardBrake_1037 Generalization_ImageOnObject_1042 Generalization_ObscuredStop_1045 Generalization_ObscuredStop_1046 Generalization_ObscuredStop_1047 Generalization_ObscuredStop_1048 Generalization_OppositeConstruction_1050 Generalization_OppositeConstruction_1051 Generalization_OppositeConstruction_1052 Generalization_OppositeConstruction_1053 Generalization_OppositeConstruction_1054 Generalization_PassableObstacles_1061 Generalization_PassableObstacles_1062 Generalization_PassableObstacles_1063 Generalization_PassableObstacles_1064 Generalization_PedestrianCrowd_1067 Generalization_PedestrianCrowd_1068 Generalization_PedestrianOtherBlocker_1070 Generalization_PedestrianOtherBlocker_1071 Generalization_PedestriansOnRoad_1086 Generalization_PedestriansOnRoad_1089 Generalization_RightConstruction_1090 Generalization_RightConstruction_1092 Generalization_RightOfWay_1055 Generalization_RightOfWay_1056 Generalization_RightOfWay_1059}"

exec bash "$SCRIPT_DIR/launch_latest_4hz_stage3_ds87_epoch9_fail2drive_seed0_8gpu.sh" "$@"
